{
    "name": "drupal/openculturas_project",
    "description": "The OpenCulturas project template.",
    "license": "GPL-2.0-or-later",
    "type": "project",
    "homepage": "https://www.openculturas.org",
    "require": {
        "composer/installers": "^2.3",
        "cweagans/composer-patches": "^2.0",
        "drupal/core": "~11.4.8",
        "drupal/core-composer-scaffold": "~11.4.8",
        "drupal/core-project-message": "~11.4.8",
        "drupal/user_restrictions": "^2.1.1",
        "drush/drush": "^13.8.0",
        "openculturas/openculturas-distribution": "~3.1.0"
    },
    "conflict": {
        "drupal/drupal": "*"
    },
    "repositories": [
        {
            "type": "composer",
            "url": "https://packages.drupal.org/8"
        },
        {
            "type": "package",
            "package": {
                "name": "leaflet/leaflet.fullscreen",
                "type": "drupal-library",
                "version": "v1.0.2",
                "dist": {
                    "type": "zip",
                    "url": "https://github.com/leaflet/leaflet.fullscreen/archive/refs/tags/v1.0.2.zip"
                }
            }
        },
        {
            "type": "package",
            "package": {
                "name": "elmarquis/leaflet.gesture-handling",
                "type": "drupal-library",
                "version": "v1.2.2",
                "dist": {
                    "type": "zip",
                    "url": "https://github.com/elmarquis/leaflet.gestureHandling/archive/refs/tags/v1.2.2.zip"
                }
            }
        },
        {
            "type": "package",
            "package": {
                "name": "leaflet/leaflet.markercluster",
                "type": "drupal-library",
                "version": "v1.5.3",
                "dist": {
                    "type": "zip",
                    "url": "https://github.com/leaflet/leaflet.markercluster/archive/refs/tags/v1.5.3.zip"
                }
            }
        },
        {
            "type": "package",
            "package": {
                "name": "perliedman/leaflet-control-geocoder",
                "type": "drupal-library",
                "version": "2.4.0",
                "dist": {
                    "type": "tar",
                    "url": "https://registry.npmjs.org/leaflet-control-geocoder/-/leaflet-control-geocoder-2.4.0.tgz"
                }
            }
        },
        {
            "type": "package",
            "package": {
                "name": "brianvoe/slim-select",
                "type": "drupal-library",
                "version": "2.13.1",
                "dist": {
                    "type": "tar",
                    "url": "https://registry.npmjs.org/slim-select/-/slim-select-2.13.1.tgz"
                }
            }
        },
        {
            "type": "package",
            "package": {
                "name": "choices-js/choices.js",
                "type": "drupal-library",
                "version": "v10.2.0",
                "dist": {
                    "type": "zip",
                    "url": "https://github.com/choices-js/choices/archive/refs/tags/v10.2.0.zip"
                }
            }
        },
        {
            "type": "package",
            "package": {
                "name": "heiseonline/shariff",
                "type": "drupal-library",
                "version": "3.2.1",
                "dist": {
                    "type": "zip",
                    "url": "https://github.com/heiseonline/shariff/releases/download/3.2.1/shariff-3.2.1.zip"
                }
            }
        },
        {
            "type": "package",
            "package": {
                "name": "ajaxorg/ace-builds",
                "type": "drupal-library",
                "version": "1.44.0",
                "extra": {
                    "installer-name": "ace-builds"
                },
                "dist": {
                    "type": "zip",
                    "url": "https://github.com/ajaxorg/ace-builds/archive/refs/tags/v1.44.0.zip"
                }
            }
        },
        {
            "type": "package",
            "package": {
                "name": "fortawesome/font-awesome",
                "type": "drupal-library",
                "version": "6.7.2",
                "extra": {
                    "installer-name": "font-awesome"
                },
                "dist": {
                    "type": "zip",
                    "url": "https://github.com/fortawesome/font-awesome/archive/refs/tags/6.7.2.zip"
                }
            }
        },
        {
            "type": "package",
            "package": {
                "name": "fengyuanchen/cropperjs",
                "type": "drupal-library",
                "version": "v1.6.3",
                "extra": {
                    "installer-name": "cropperjs"
                },
                "dist": {
                    "type": "zip",
                    "url": "https://github.com/fengyuanchen/cropperjs/archive/refs/tags/v1.6.3.zip"
                }
            }
        }
    ],
    "minimum-stability": "alpha",
    "prefer-stable": true,
    "config": {
        "allow-plugins": {
            "composer/installers": true,
            "cweagans/composer-patches": true,
            "drupal/core-composer-scaffold": true,
            "drupal/core-project-message": true,
            "php-http/discovery": false,
            "symfony/runtime": true
        },
        "optimize-autoloader": true,
        "platform": {
            "php": "8.4"
        },
        "preferred-install": "dist",
        "sort-packages": true
    },
    "extra": {
        "composer-exit-on-patch-failure": true,
        "drupal-core-project-message": {
            "include-keys": [
                "homepage",
                "support"
            ],
            "post-create-project-cmd-message": [
                "<fg=magenta>                                                               </>",
                "<fg=magenta>  Congratulations, you’ve installed the OpenCulturas codebase  </>",
                "<fg=magenta>  from the drupal/openculturas-project template!         </>",
                "<fg=magenta>                                                               </>",
                "",
                "  * Remove the plugin that prints this message:",
                "      composer remove drupal/core-project-message"
            ]
        },
        "drupal-scaffold": {
            "file-mapping": {
                "[web-root]/.csslintrc": false,
                "[web-root]/.ht.router.php": false,
                "[web-root]/INSTALL.txt": false,
                "[web-root]/README.md": false,
                "[web-root]/example.gitignore": false,
                "[web-root]/modules/README.txt": false,
                "[web-root]/profiles/README.txt": false,
                "[web-root]/sites/README.txt": false,
                "[web-root]/sites/development.services.yml": {
                    "mode": "replace",
                    "overwrite": false,
                    "path": "assets/development.services.yml"
                },
                "[web-root]/sites/example.sites.php": false,
                "[web-root]/themes/README.txt": false,
                "[web-root]/web.config": false
            },
            "locations": {
                "web-root": "web/"
            }
        },
        "enable-patching": true,
        "installer-paths": {
            "web/core": [
                "type:drupal-core"
            ],
            "web/libraries/{$name}": [
                "type:drupal-library"
            ],
            "web/modules/contrib/{$name}": [
                "type:drupal-module"
            ],
            "web/profiles/contrib/{$name}": [
                "type:drupal-profile"
            ],
            "web/themes/contrib/{$name}": [
                "type:drupal-theme"
            ],
            "drush/Commands/contrib/{$name}": [
                "type:drupal-drush"
            ],
            "web/modules/custom/{$name}": [
                "type:drupal-custom-module"
            ],
            "web/profiles/custom/{$name}": [
                "type:drupal-custom-profile"
            ],
            "web/themes/custom/{$name}": [
                "type:drupal-custom-theme"
            ]
        },
        "patches": {}
    }
}
